<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue';import { useRouter } from 'vue-router';import { ArrowLeft,ArrowRight,Check,UserRound,GraduationCap,Target,Languages,Files,ClipboardCheck,UploadCloud } from 'lucide-vue-next';import type { UserProfile } from '../types';import { useAppState } from '../composables/useAppState'
const router=useRouter(),{profile,session,toast}=useAppState(),error=ref('');const saved=(()=>{try{return JSON.parse(localStorage.getItem('minerva-onboarding-draft')||'null') as UserProfile|null}catch{return null}})(),step=ref(Math.max(0,Math.min(5,Number(localStorage.getItem('minerva-onboarding-step')||0))));const steps: [string, any][]=[['Personal information',UserRound],['Last education',GraduationCap],['Scholarship goals',Target],['English proficiency',Languages],['Base documents',Files],['Review profile',ClipboardCheck]];const d:UserProfile={name:session.value?.name||'',age:null,country:'Indonesia',destinationCountry:'',currentEducationLevel:'',targetEducationLevel:'Master',fieldOfStudy:'',scholarshipType:'Government',fundingPreference:'Fully funded',englishLevel:'Intermediate',ieltsScore:'',availableDocuments:[],enrollmentYear:'2027'};const seed=saved||profile.value||d,form=reactive<UserProfile>({...seed,availableDocuments:[...seed.availableDocuments]}),docs=['CV','Essay','Personal statement','Study plan','Research plan','Recommendation letter','Academic transcript','IELTS certificate','Passport'],uploaded=ref<Record<string,string>>({});watch(form,v=>localStorage.setItem('minerva-onboarding-draft',JSON.stringify(v)),{deep:true});watch(step,v=>localStorage.setItem('minerva-onboarding-step',String(v)));const upload=(x:string,e:Event)=>{const f=(e.target as HTMLInputElement).files?.[0];if(f){uploaded.value={...uploaded.value,[x]:f.name};if(!form.availableDocuments.includes(x))form.availableDocuments.push(x)}};const done=(i:number)=>[!!(form.name.trim()&&form.age&&form.country),!!(form.currentEducationLevel&&form.targetEducationLevel&&form.fieldOfStudy.trim()),!!(form.destinationCountry&&form.enrollmentYear&&form.scholarshipType&&form.fundingPreference),!!form.englishLevel,true,false][i];const progress=computed(()=>Math.round(Array.from({length:5},(_,i)=>done(i)).filter(Boolean).length/5*100));const go=(i:number)=>{if(i>step.value&&!done(step.value)){error.value='Complete the required fields on this step before moving forward.';return}error.value='';step.value=i};const next=()=>go(step.value+1);const save=()=>{if(!Array.from({length:5},(_,i)=>done(i)).every(Boolean)){error.value='Complete every required tab before saving your profile.';return}profile.value={...form,availableDocuments:[...form.availableDocuments]};localStorage.removeItem('minerva-onboarding-draft');localStorage.removeItem('minerva-onboarding-step');toast('Your profile is ready. Welcome to Minerva!');router.push('/dashboard')}
watch(step, (value) => { if (value === 3) step.value = 4 })
</script>
<template><main class="bg-[#fbfbfe] py-10 sm:py-16"><div class="container max-w-6xl"><div class="grid gap-8 lg:grid-cols-[280px_1fr]"><aside class="card h-max p-5"><img src="/minerva-logo.png" alt="Minerva" class="h-14 w-44 object-contain"><p class="mt-7 text-xs font-extrabold uppercase tracking-wider text-slate-400">Profile progress · {{progress}}%</p><div class="mt-3 h-2 rounded-full bg-slate-100"><div class="h-full rounded-full bg-gradient-to-r from-[#5b45f5] to-[#27a8f7]" :style="{width:`${progress}%`}"/></div><div class="mt-6 grid gap-2"><button v-for="(x,i) in steps" :key="x[0]" class="flex items-center gap-3 rounded-xl p-3 text-left text-sm font-bold" :class="i===step?'bg-violet-50 text-[#5b45f5]':done(i)?'text-emerald-600':'text-slate-400'" @click="go(i)"><Check v-if="done(i)&&i!==step" :size="18"/><component v-else :is="x[1]" :size="18"/><span>{{x[0]}}</span></button></div></aside><section class="card min-h-[650px] p-6 sm:p-10"><p class="eyebrow">Step {{step+1}} of 6</p><h1 class="mt-5 text-3xl font-extrabold text-[#17136b]">{{steps[step][0]}}</h1><p class="mt-3 text-slate-500">Your progress saves automatically. Required fields must be completed before moving forward.</p><div class="mt-9"><div v-if="step===0" class="grid gap-5 sm:grid-cols-2"><label class="field-label sm:col-span-2">Full name<input v-model="form.name" class="field"></label><label class="field-label">Age<input v-model.number="form.age" type="number" min="15" class="field"></label><label class="field-label">Country<select v-model="form.country" class="field"><option value="">Select country</option><option>Indonesia</option><option>Malaysia</option><option>Singapore</option><option>India</option><option>Other</option></select></label></div><div v-else-if="step===1" class="grid gap-5 sm:grid-cols-2"><label class="field-label">Last education<select v-model="form.currentEducationLevel" class="field"><option value="">Select level</option><option>High school</option><option>Bachelor</option><option>Master</option><option>Doctorate</option></select></label><label class="field-label">Target education<select v-model="form.targetEducationLevel" class="field"><option value="">Select level</option><option>Bachelor</option><option>Master</option><option>Doctorate</option></select></label><label class="field-label sm:col-span-2">Field of study<input v-model="form.fieldOfStudy" class="field"></label></div><div v-else-if="step===2" class="grid gap-5 sm:grid-cols-2"><label class="field-label">Destination<select v-model="form.destinationCountry" class="field"><option value="">Choose destination</option><option>United Kingdom</option><option>Germany</option><option>Australia</option><option>Japan</option><option>United States</option></select></label><label class="field-label">Enrollment year<select v-model="form.enrollmentYear" class="field"><option value="">Choose year</option><option>2027</option><option>2028</option><option>2029</option></select></label><label class="field-label">Scholarship type<select v-model="form.scholarshipType" class="field"><option value="">Choose type</option><option>Government</option><option>University</option><option>International</option></select></label><label class="field-label">Funding<select v-model="form.fundingPreference" class="field"><option value="">Choose funding</option><option>Fully funded</option><option>Partial funding</option><option>Either</option></select></label></div><div v-else-if="step===3"><label class="field-label max-w-sm">English level<select v-model="form.englishLevel" class="field"><option value="">Select level</option><option>Beginner</option><option>Intermediate</option><option>Upper intermediate</option><option>Advanced</option></select></label><p class="mt-4 text-sm text-slate-500">Add your IELTS certificate, if available, in Base Documents.</p></div><div v-else-if="step===4"><p class="rounded-2xl bg-violet-50 p-4 text-sm text-[#40348d]">Base documents are optional master copies; this tab is complete with or without uploads.</p><div class="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><div v-for="doc in docs" :key="doc" class="rounded-xl border p-3"><label class="text-sm font-bold text-[#17136b]"><input v-model="form.availableDocuments" type="checkbox" :value="doc" class="mr-2 accent-[#5b45f5]">{{doc}}</label><label class="mt-2 flex cursor-pointer gap-2 text-xs font-bold text-[#5b45f5]"><UploadCloud :size="14"/>{{uploaded[doc]||'Upload'}}<input type="file" class="sr-only" @change="upload(doc,$event)"></label></div></div></div><div v-else><div class="grid gap-4 sm:grid-cols-2"><div v-for="x in [['Name',form.name],['Country',form.country],['Destination',form.destinationCountry],['Field',form.fieldOfStudy]]" :key="x[0]" class="rounded-xl border p-4"><p class="text-xs text-slate-400">{{x[0]}}</p><p class="font-extrabold text-[#17136b]">{{x[1]||'Not provided'}}</p></div><div class="rounded-xl border p-4 sm:col-span-2"><p class="text-xs font-bold uppercase text-slate-400">Base documents</p><div class="mt-2 flex flex-wrap gap-2"><span v-for="doc in form.availableDocuments" :key="doc" class="tag">{{doc}}</span><span v-if="!form.availableDocuments.length" class="text-sm text-slate-400">None selected — that is okay.</span></div></div></div></div></div><p v-if="error" class="error mt-4">{{error}}</p><div class="onboarding-actions"><button class="btn-secondary" :class="step===0&&'invisible'" @click="step--"><ArrowLeft :size="16"/>Back</button><button v-if="step<5" class="btn-primary" @click="next">Continue<ArrowRight :size="16"/></button><button v-else class="btn-primary" @click="save">Save profile<Check :size="16"/></button></div></section></div></div></main></template>
